# Validated field name -> key selector. Ordering is done in Python so that no
# request-supplied value is ever interpolated into SQL.
_SORT_KEYS = {
    "id": lambda user: user["id"],
    "name": lambda user: user["name"],
    "email": lambda user: user["email"],
}


def list_users_sorted(sort: str = "id", order: str = "asc") -> list[dict]:
    return sorted(store.list_users(), key=_SORT_KEYS[sort], reverse=order == "desc")

